/**
 * @event
 * @name scwin.dataTb_oncellclick
 * @author Inswave
 * @date 2026. 09. 29
 * @param rowIndex columnIndex columnId
 * @returns
 * @hidden N
*/
scwin.dataTb_oncellclick = async function (rowIndex, columnIndex, columnId) {
    try {
        const dl = $c.util.getComponent('dlt_result');
        if (!dl) { console.error('[sdd] 행 동작 대상 목록 없음: dlt_result'); return; }
        const r = dl.getRowJSON ? dl.getRowJSON(rowIndex) : null;
        if (!r) { return; }
        if (columnId === "__rowAct") { if (r["stdCdGrntFeeProcsStatCd"] !== '5' && r["stdCdGrntFeeProcsStatCd"] !== '9') { if (typeof scwin.PopUp_FeeReport === 'function') { scwin.PopUp_FeeReport(r["stdCdApplId"]); } else { console.error('[sdd] 행 동작 미정의: scwin.PopUp_FeeReport (열 ?)'); await $c.win.alert('이 행 동작을 아직 정하지 못했습니다(전환 미완) — scwin.PopUp_FeeReport'); } return; } return; } if (typeof scwin.onPopupCode === 'function') { await scwin.onPopupCode(r["mktCd"], r["stdCd"]); } else { console.error('[sdd] 행 동작 미정의: scwin.onPopupCode (열 ?)'); await $c.win.alert('이 행 동작을 아직 정하지 못했습니다(전환 미완) — scwin.onPopupCode'); } return;
    } catch (e) {
        await $c.exception.handleError(e, { notify: 'none', context: 'dataTb.oncellclick' });
    }
};


