    $.ajax({ type: "POST", async: false, url: "/fee/fee.do?method=feeReportCommonAjax&std_cd_appl_id=" + std_cd_appl_id, data: {  }, success: async function(data) {
                const result = (typeof data === "string" ? (typeof data === "string" ? JSON.parse(data) : data) : data);
                const form = (document.newReportForm || { elements: [] });
                for (key in result) {
                    if (form[camelize(key)]) {
                        form[camelize(key)].value = result[key];
                    }
                }
                $c.util.getComponent('dma_prepayReq').set('isurNm', result.com_nm);
                await scwin.tx_PopUp_FeeReport();
            }, error: async function(request, status, error) {
                await $c.win.alert("장애발생.");
                return;
            }, complete: function() {

            } });
    /* sdd-asis-lifecycle:end */
};


